package com.bank.leaderboard;

import java.util.*;
import java.util.logging.*;

public class SortByValueDemo {
    private static final Logger log = Logger.getLogger("Leaderboard");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Map<String, Double> salaries = new HashMap<>();
        salaries.put("Priya", 250000.0);
        salaries.put("Rajesh", 1000000.0);
        salaries.put("Amit", 400000.0);
        LeaderboardService service = new LeaderboardService();

        Map<String, Double> ranked = service.rankBySalaryDesc(salaries);
        log.info(() -> "Ranked (high → low): " + ranked);
    }
}

// ─── Would be in service/LeaderboardService.java ───
class LeaderboardService {
    Map<String, Double> rankBySalaryDesc(Map<String, Double> salaries) {
        return salaries.entrySet().stream()
            .sorted(Map.Entry.<String, Double>comparingByValue(Comparator.reverseOrder())) // desc
            .collect(java.util.stream.Collectors.toMap(
                Map.Entry::getKey, Map.Entry::getValue,
                (a, b) -> a,                 // merge (unused, keys unique)
                LinkedHashMap::new));        // preserve sorted order
    }
}
